import{_ as e,c as o,o as a,a4 as t}from"./chunks/framework.CpVK_f0P.js";const p=JSON.parse('{"title":"语法错误记录","description":"","frontmatter":{},"headers":[],"relativePath":"mistakes/grammar.md","filePath":"mistakes/grammar.md"}'),r={name:"mistakes/grammar.md"},n=t('<h1 id="语法错误记录" tabindex="-1">语法错误记录 <a class="header-anchor" href="#语法错误记录" aria-label="Permalink to &quot;语法错误记录&quot;">​</a></h1><blockquote><p>只记录真实训练中犯过的语法错误。不系统整理完整语法知识。</p></blockquote><h2 id="过去时态" tabindex="-1">过去时态 <a class="header-anchor" href="#过去时态" aria-label="Permalink to &quot;过去时态&quot;">​</a></h2><h3 id="find-的过去式" tabindex="-1">find 的过去式 <a class="header-anchor" href="#find-的过去式" aria-label="Permalink to &quot;find 的过去式&quot;">​</a></h3><ul><li>✗ He finally <strong>founded</strong> the address.</li><li>✓ He finally <strong>found</strong> the address.</li></ul><p><code>found</code> 是 <code>find</code> 的过去式，意思是&quot;找到&quot;。<code>founded</code> 是 <code>found</code> 的过去式，意思是&quot;创立、建立&quot;。</p><h3 id="复述时时态混用" tabindex="-1">复述时时态混用 <a class="header-anchor" href="#复述时时态混用" aria-label="Permalink to &quot;复述时时态混用&quot;">​</a></h3><p>在复述一段过去的故事时，容易不自觉地切换回现在时：</p><ul><li><p>✗ Harry <strong>doesn&#39;t</strong> know how to get there.</p></li><li><p>✓ Harry <strong>didn&#39;t</strong> know how to get there.</p></li><li><p>✗ They <strong>go</strong> to the restaurant.</p></li><li><p>✓ They <strong>went</strong> to the restaurant.</p></li></ul><p><strong>提醒</strong>：复述开始前先确认时态基调。如果是在说过去发生的事，全程保持过去时。</p><h2 id="冠词" tabindex="-1">冠词 <a class="header-anchor" href="#冠词" aria-label="Permalink to &quot;冠词&quot;">​</a></h2><h3 id="可数名词单数需要冠词" tabindex="-1">可数名词单数需要冠词 <a class="header-anchor" href="#可数名词单数需要冠词" aria-label="Permalink to &quot;可数名词单数需要冠词&quot;">​</a></h3><ul><li><p>✗ He met <strong>old woman</strong>.</p></li><li><p>✓ He met <strong>an old woman</strong>.</p></li><li><p>✗ They went to <strong>restaurant</strong>.</p></li><li><p>✓ They went to <strong>the restaurant</strong>.</p></li></ul><h3 id="a-和-an-的选择" tabindex="-1">a 和 an 的选择 <a class="header-anchor" href="#a-和-an-的选择" aria-label="Permalink to &quot;a 和 an 的选择&quot;">​</a></h3><p>元音音素前用 an：</p><ul><li>an old woman</li><li>an hour</li><li>an interesting story</li></ul><h2 id="ask-的句型" tabindex="-1">ask 的句型 <a class="header-anchor" href="#ask-的句型" aria-label="Permalink to &quot;ask 的句型&quot;">​</a></h2><h3 id="ask-someone-how-to" tabindex="-1">ask someone how to... <a class="header-anchor" href="#ask-someone-how-to" aria-label="Permalink to &quot;ask someone how to...&quot;">​</a></h3><ul><li>✗ He asked the woman <strong>for how to</strong> get to the street.</li><li>✓ He asked the woman <strong>how to</strong> get to the street.</li></ul><p><code>ask someone how to do something</code> 中间不需要 <code>for</code>。</p><p><code>ask someone for something</code> 用于请求具体的东西：</p><ul><li>He asked her <strong>for help</strong>.</li><li>He asked her <strong>for directions</strong>.</li></ul>',22),s=[n];function l(i,d,h,c,u,m){return a(),o("div",null,s)}const f=e(r,[["render",l]]);export{p as __pageData,f as default};
